// LDAPS configuration — env-driven, validated with Zod (the scaffold's stack).
// Every knob is an env var so the same component drops into any project; see
// USAGE.md for the full list and examples.
import { z } from 'zod';

const envSchema = z.object({
  /** e.g. ldaps://dc01.corp.example.com:636 (ldap:// + STARTTLS also works) */
  LDAP_URL: z.string().min(1),
  /** Service account used to search for users, e.g. cn=svc-app,ou=service,dc=corp,dc=example,dc=com */
  LDAP_BIND_DN: z.string().min(1),
  LDAP_BIND_PASSWORD: z.string().min(1),
  /** Search base, e.g. dc=corp,dc=example,dc=com */
  LDAP_BASE_DN: z.string().min(1),
  /**
   * User search filter; {{username}} is replaced with the (escaped) login name.
   * The default matches AD (sAMAccountName), POSIX (uid) and mail logins.
   */
  LDAP_USER_FILTER: z
    .string()
    .default('(&(objectClass=person)(|(sAMAccountName={{username}})(uid={{username}})(mail={{username}})))'),
  /** Attribute holding group DNs on the user entry (AD: memberOf). */
  LDAP_GROUP_ATTR: z.string().default('memberOf'),
  /** Path to a PEM CA bundle for a private CA; omit when the cert chain is public. */
  LDAP_CA_CERT_PATH: z.string().optional(),
  /** Set to 'false' ONLY in a lab — never in production. */
  LDAP_TLS_REJECT_UNAUTHORIZED: z.enum(['true', 'false']).default('true'),
  LDAP_POOL_SIZE: z.coerce.number().int().min(1).max(20).default(4),
  LDAP_TIMEOUT_MS: z.coerce.number().int().min(500).max(60000).default(5000),
});

export type LdapsConfig = z.infer<typeof envSchema>;

export function loadLdapsConfig(env: NodeJS.ProcessEnv = process.env): LdapsConfig {
  const parsed = envSchema.safeParse(env);
  if (!parsed.success) {
    const missing = parsed.error.issues.map((i) => i.path.join('.')).join(', ');
    throw new Error(`LDAPS config invalid or missing: ${missing}`);
  }
  return parsed.data;
}

// LDAPS connection handling — a small bounded pool of ldapts clients over TLS.
// Dependency: npm install ldapts   (see USAGE.md)
import { Client } from 'ldapts';
import { readFileSync } from 'node:fs';
import type { LdapsConfig } from './config.js';

export interface PooledClient {
  client: Client;
  release: () => void;
}

// Bounded lazy pool: connections are created on demand up to LDAP_POOL_SIZE and
// reused across requests; a broken connection is discarded on release.
export class LdapsPool {
  private idle: Client[] = [];
  private size = 0;
  private waiters: Array<(c: Client) => void> = [];

  constructor(private readonly cfg: LdapsConfig) {}

  private tlsOptions() {
    return {
      rejectUnauthorized: this.cfg.LDAP_TLS_REJECT_UNAUTHORIZED !== 'false',
      ...(this.cfg.LDAP_CA_CERT_PATH ? { ca: readFileSync(this.cfg.LDAP_CA_CERT_PATH) } : {}),
    };
  }

  private create(): Client {
    return new Client({
      url: this.cfg.LDAP_URL,
      timeout: this.cfg.LDAP_TIMEOUT_MS,
      connectTimeout: this.cfg.LDAP_TIMEOUT_MS,
      tlsOptions: this.tlsOptions(),
    });
  }

  async acquire(): Promise<PooledClient> {
    const existing = this.idle.pop();
    const client = existing
      ?? (this.size < this.cfg.LDAP_POOL_SIZE
        ? (this.size++, this.create())
        : await new Promise<Client>((resolve) => this.waiters.push(resolve)));
    let released = false;
    return {
      client,
      release: () => {
        if (released) return;
        released = true;
        if (!client.isConnected) {
          // Broken connection: drop it; the next acquire creates a fresh one.
          this.size--;
          void client.unbind().catch(() => undefined);
          const waiter = this.waiters.shift();
          if (waiter) { this.size++; waiter(this.create()); }
          return;
        }
        const waiter = this.waiters.shift();
        if (waiter) waiter(client);
        else this.idle.push(client);
      },
    };
  }

  /** Service-account bind on a pooled connection; caller must release(). */
  async acquireBound(): Promise<PooledClient> {
    const pooled = await this.acquire();
    try {
      await pooled.client.bind(this.cfg.LDAP_BIND_DN, this.cfg.LDAP_BIND_PASSWORD);
      return pooled;
    } catch (err) {
      pooled.release();
      throw err;
    }
  }

  async close(): Promise<void> {
    const all = [...this.idle];
    this.idle = [];
    this.size = 0;
    await Promise.allSettled(all.map((c) => c.unbind()));
  }
}

// LDAPS authentication: search-then-bind with group extraction.
// authenticate() is the only call the app's login route needs.
import { LdapsPool } from './client.js';
import { loadLdapsConfig, type LdapsConfig } from './config.js';

export interface LdapsUser {
  dn: string;
  username: string;
  displayName: string | null;
  email: string | null;
  /** Group DNs from LDAP_GROUP_ATTR (AD: memberOf). */
  groups: string[];
}

// RFC 4515 filter escaping — user input must never reach a filter raw.
export function escapeLdapFilterValue(value: string): string {
  return value.replace(/[\\*()\0]/g, (ch) => {
    switch (ch) {
      case '\\': return '\\5c';
      case '*': return '\\2a';
      case '(': return '\\28';
      case ')': return '\\29';
      default: return '\\00';
    }
  });
}

let defaultPool: LdapsPool | null = null;
let defaultCfg: LdapsConfig | null = null;

function ensurePool(): { pool: LdapsPool; cfg: LdapsConfig } {
  if (!defaultPool || !defaultCfg) {
    defaultCfg = loadLdapsConfig();
    defaultPool = new LdapsPool(defaultCfg);
  }
  return { pool: defaultPool, cfg: defaultCfg };
}

/** Look up a user entry (service-account credentials). Null when not found. */
export async function findUser(username: string): Promise<LdapsUser | null> {
  const { pool, cfg } = ensurePool();
  const filter = cfg.LDAP_USER_FILTER.replaceAll('{{username}}', escapeLdapFilterValue(username));
  const pooled = await pool.acquireBound();
  try {
    const { searchEntries } = await pooled.client.search(cfg.LDAP_BASE_DN, {
      scope: 'sub',
      filter,
      sizeLimit: 2,
      attributes: ['dn', 'displayName', 'cn', 'mail', cfg.LDAP_GROUP_ATTR],
    });
    if (searchEntries.length !== 1) return null; // absent or ambiguous — both refuse
    const e = searchEntries[0];
    const groupsRaw = e[cfg.LDAP_GROUP_ATTR];
    const groups = (Array.isArray(groupsRaw) ? groupsRaw : groupsRaw ? [groupsRaw] : [])
      .map((g) => String(g));
    return {
      dn: String(e.dn),
      username,
      displayName: e.displayName ? String(e.displayName) : e.cn ? String(e.cn) : null,
      email: e.mail ? String(e.mail) : null,
      groups,
    };
  } finally {
    pooled.release();
  }
}

/**
 * Verify credentials: find the user, then bind AS the user with the supplied
 * password on a separate pooled connection. Returns the profile on success,
 * null on unknown user / wrong password (indistinguishable to the caller —
 * never leak which one failed).
 */
export async function authenticate(username: string, password: string): Promise<LdapsUser | null> {
  if (!username || !password) return null; // an empty password would be an anonymous bind
  const user = await findUser(username);
  if (!user) return null;
  const { pool } = ensurePool();
  const pooled = await pool.acquire();
  try {
    await pooled.client.bind(user.dn, password);
    await pooled.client.unbind(); // drop the user-bound session; pool reconnects
    return user;
  } catch {
    return null;
  } finally {
    pooled.release();
  }
}

/** Group check by full DN or bare CN (case-insensitive). */
export function userInGroup(user: LdapsUser, group: string): boolean {
  const want = group.toLowerCase();
  return user.groups.some((g) => {
    const dn = g.toLowerCase();
    if (dn === want) return true;
    const cn = dn.split(',')[0]?.replace(/^cn=/, '');
    return cn === want;
  });
}

/** Call on shutdown so the pool's sockets close cleanly. */
export async function closeLdaps(): Promise<void> {
  if (defaultPool) { await defaultPool.close(); defaultPool = null; defaultCfg = null; }
}
